export declare const INCRBY_WITH_EXPIRE = "\nlocal v = redis.call(\"INCRBY\", KEYS[1], ARGV[1])\nif v == tonumber(ARGV[1]) then\n  redis.call(\"EXPIRE\", KEYS[1], tonumber(ARGV[2]))\nend\nreturn v\n";
export declare const DECRBY_OR_DELETE = "\nif redis.call(\"EXISTS\", KEYS[1]) == 0 then return 0 end\nlocal v = redis.call(\"DECRBY\", KEYS[1], ARGV[1])\nif v <= 0 then redis.call(\"DEL\", KEYS[1]) end\nreturn v\n";
export declare const PUSH_UNIQUE = "\nlocal repeats = 1\nfor _, v in ipairs(redis.call(\"LRANGE\", KEYS[1], 0, -1)) do\n  local ok, d = pcall(cjson.decode, v)\n  if ok and type(d) == \"table\" and d.sig == ARGV[2] then\n    repeats = repeats + (tonumber(d.repeats) or 1)\n    redis.call(\"LREM\", KEYS[1], 0, v)\n  end\nend\nlocal item = ARGV[1]\nif repeats > 1 then item = '{\"repeats\":' .. repeats .. ',' .. string.sub(ARGV[1], 2) end\nredis.call(\"LPUSH\", KEYS[1], item)\nredis.call(\"LTRIM\", KEYS[1], 0, tonumber(ARGV[3]) - 1)\nredis.call(\"EXPIRE\", KEYS[1], tonumber(ARGV[4]))\nreturn repeats\n";
